contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will deposit 'amount' then call withdrawAll and assert that if withdrawAll does not revert,
    // then address(c).balance is equal to the balance right after deposit minus any transfer out
    // (i.e., it did not secretly increase the recorded credit for this caller). We cannot read credit mapping,
    // so we observe via address(c).balance and address(this).balance.

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record balances before any interaction
        uint c_bal_before = address(c).balance;
        uint t_bal_before = address(this).balance;

        // deposit amount into c
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // record balances after deposit
        uint c_bal_after_deposit = address(c).balance;
        uint t_bal_after_deposit = address(this).balance;

        // ensure deposit had expected observable effect: c balance increased by amount
        // (this is a precondition check expressed as require so test is only meaningful for such runs)
        require(c_bal_after_deposit == c_bal_before + amount);
        require(t_bal_after_deposit == t_bal_before - amount);

        // call withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // balances after withdraw attempt
        uint c_bal_final = address(c).balance;
        uint t_bal_final = address(this).balance;

        // Assert general invariant: if withdrawAll did not revert, then after it the caller's credit must be cleared
        // which observable implies that the contract's balance did not increase relative to immediately after deposit.
        // Formally: if not reverted then c_bal_final <= c_bal_after_deposit and the caller's balance did not decrease
        // compared to after deposit (it should be >= t_bal_after_deposit). Together these rule out secretly increasing credit.
        assert(reverted || (c_bal_final <= c_bal_after_deposit && t_bal_final >= t_bal_after_deposit));
    }

    receive() external payable { }
}

