// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint c_bal_before = address(c).balance;
        uint t_bal_before = address(this).balance;
        try c.deposit{value: amount}() {} catch { return; }
        uint c_bal_after_deposit = address(c).balance;
        uint t_bal_after_deposit = address(this).balance;
        vm.assume(c_bal_after_deposit == c_bal_before + amount);
        vm.assume(t_bal_after_deposit == t_bal_before - amount);
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint c_bal_final = address(c).balance;
        uint t_bal_final = address(this).balance;
        assertTrue(reverted || (c_bal_final <= c_bal_after_deposit && t_bal_final >= t_bal_after_deposit));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { }
}
